  6	// Canonical error registry (ADR-0019). Error identity is (domain, reason),
  7	// carried on the wire as google.rpc.ErrorInfo — which this file deliberately
  8	// does NOT import: referencing it emits Rust and TypeScript pointing at modules
  9	// buf never generates. See the SMA-498 design doc §2.1.
 10	//
 11	// These enums are REGISTRIES, never wire types. No field anywhere is of type
 12	// ErrorReason or ErrorDomain; the wire carries strings.
 13	//
 14	// Mapping rules (normative):
 15	//   reason: strip ERROR_REASON_, lowercase, '_' -> '-'
 16	//   domain: strip ERROR_DOMAIN_, lowercase, '_' -> '-', append '.paigasus.io'
 17	// Each value's comment repeats the resulting literal verbatim. Kebab casing is
 18	// a deliberate, documented deviation from Google's UPPER_SNAKE reason
 19	// convention (ADR-0019 decision 3).
 20	//
 21	// THE REGISTRY IS APPEND-ONLY. Removing a value is a breaking change. Retract
 22	// only by reserving both name and number. buf breaking is NOT what protects
 23	// this vocabulary — it cannot see the kebab strings, cannot tell whether a code
 24	// is still emitted or consumed, and does not run against Rust or TypeScript.
 25	// The two-way drift gate (SMA-507) is the real guard.
 26	//
 27	// Numbering encodes which domain may emit a code, so the drift gate can derive
 28	// it arithmetically:
 29	//   1-299    IAM only
 30	//   300-599  gateway only
 31	//   600-899  reserved for a future domain (e.g. ERROR_DOMAIN_MODEL_ROUTER)
 32	//   900-999  shared — any domain may emit
 33	// Sub-group banners below are documentation only and carry no numbering
 34	// meaning; a new IAM code takes the next free number in 1-299.
 35	//
 36	// ErrorInfo.metadata carries these standard keys, populated by SMA-504:
 37	// `retryable` (exactly "true" | "false" | "unknown"), `correlation_id` and
 38	// `request_id` (present only when the error was produced inside a request
 39	// scope), and `capability` (only on ERROR_REASON_CAPABILITY_DISABLED). They
 40	// are prose here, not enumerated: metadata is an open map, not a closed
 41	// vocabulary consumers branch on exhaustively. The append-only guarantee
 42	// above covers reasons and domains ONLY, not metadata keys.
 43	
 44	// The service that produced an error. Not emitted on the gateway's
 45	// OpenAI-compatible envelope, which has no domain field and carries only
 46	// `code`; it applies wherever ErrorInfo itself travels.
 47	enum ErrorDomain {
 48	  ERROR_DOMAIN_UNSPECIFIED = 0;
 49	
 50	  // "iam.paigasus.io"
 51	  ERROR_DOMAIN_IAM = 1;
 52	
 53	  // "gateway.paigasus.io"
 54	  ERROR_DOMAIN_GATEWAY = 2;
 55	}
 56	
 57	// The canonical error vocabulary. See the file comment for the mapping rule,
 58	// the append-only guarantee and the numbering ranges.
 59	enum ErrorReason {
 60	  ERROR_REASON_UNSPECIFIED = 0;
 61	
 62	  // ---- IAM: tenancy (1-299) ------------------------------------------------
 63	  // Emitted verbatim today by TenancyError::code().
 64	
 65	  // "slug-conflict" — slug already taken in this scope.
 66	  ERROR_REASON_SLUG_CONFLICT = 1;
 67	  // "duplicate-membership" — principal already a member of this scope.
 68	  ERROR_REASON_DUPLICATE_MEMBERSHIP = 2;
 69	  // "email-conflict" — email address already taken.
 70	  ERROR_REASON_EMAIL_CONFLICT = 3;
 71	  // "service-account-name-conflict" — name taken under this owner node.
 72	  ERROR_REASON_SERVICE_ACCOUNT_NAME_CONFLICT = 4;
 73	  // "invalid-email" — email address failed validation.
 74	  ERROR_REASON_INVALID_EMAIL = 5;
 75	  // "invalid-slug" — slug failed validation.
 76	  ERROR_REASON_INVALID_SLUG = 6;
 77	  // "invalid-name" — name failed validation.
 78	  ERROR_REASON_INVALID_NAME = 7;
 79	  // "invalid-prn" — resource PRN failed to parse.
 80	  ERROR_REASON_INVALID_PRN = 8;
 81	  // "prn-mismatch" — PRN does not match the stored resource.
 82	  ERROR_REASON_PRN_MISMATCH = 9;
 83	  // "invalid-pagination" — limit/offset outside the accepted range.
 84	  ERROR_REASON_INVALID_PAGINATION = 10;
 85	  // "nothing-to-rename" — rename carried no new slug or name.
 86	  ERROR_REASON_NOTHING_TO_RENAME = 11;
 87	  // "not-found" — resource does not exist.
 88	  ERROR_REASON_NOT_FOUND = 12;
 89	  // "parent-archived" — parent resource is archived.
 90	  ERROR_REASON_PARENT_ARCHIVED = 13;
 91	  // "node-archived" — resource is archived.
 92	  ERROR_REASON_NODE_ARCHIVED = 14;
 93	  // "missing-org-membership" — principal is not a member of the organization.
 94	  ERROR_REASON_MISSING_ORG_MEMBERSHIP = 15;
 95	  // "forbidden" — authorization denied the request.
 96	  ERROR_REASON_FORBIDDEN = 16;
 97	  // "unknown-role" — role key is not in the role catalog.
 98	  ERROR_REASON_UNKNOWN_ROLE = 17;
 99	  // "invalid-scope" — scope PRN's node kind is outside the role's allow-list.
100	  ERROR_REASON_INVALID_SCOPE = 18;
101	  // "system-immutable" — system-owned row is immutable via the CRUD API.
102	  ERROR_REASON_SYSTEM_IMMUTABLE = 19;
103	  // "policy-invalid" — policy failed Cedar parse, schema or template-link checks.
104	  ERROR_REASON_POLICY_INVALID = 20;
105	  // "policy-conflict" — lost a concurrent-create race for this policy id.
106	  ERROR_REASON_POLICY_CONFLICT = 21;
107	  // "invalid-action" — action does not name a known Action variant.
108	  ERROR_REASON_INVALID_ACTION = 22;
109	  // "invalid-bulk-replay" — bulk replay needs an explicit non-zero max_rows.
110	  ERROR_REASON_INVALID_BULK_REPLAY = 23;
111	  // "not-system-owned" — retirement refused: the row is not system-owned.
112	  ERROR_REASON_NOT_SYSTEM_OWNED = 24;
113	  // "fleet-not-converged" — fleet is behind this binary's starter-policy revision.
114	  ERROR_REASON_FLEET_NOT_CONVERGED = 25;
115	
116	  // ---- IAM: authn (1-299) --------------------------------------------------
117	  // Emitted snake_case today; SMA-504 recases the JSON body. The RFC 6750
118	  // WWW-Authenticate challenge value `invalid_token` is standardised and stays
119	  // snake_case — only the body's `code` becomes "invalid-token".
120	
121	  // "invalid-token" — bearer token was rejected.
122	  ERROR_REASON_INVALID_TOKEN = 26;
123	  // "identity-not-provisioned" — no principal is provisioned for this identity.
124	  ERROR_REASON_IDENTITY_NOT_PROVISIONED = 27;
125	  // "provisioning-failed" — just-in-time provisioning could not complete.
126	  ERROR_REASON_PROVISIONING_FAILED = 28;
127	  // "principal-inactive" — principal exists but is not active.
128	  ERROR_REASON_PRINCIPAL_INACTIVE = 29;
129	  // "authn-unavailable" — IAM's own authentication backend is unreachable.
130	  ERROR_REASON_AUTHN_UNAVAILABLE = 30;
131	
132	  // ---- IAM: system-row retirement (1-299) ----------------------------------
133	  // Emitted verbatim today by system_retirement.rs.
134	
135	  // "grants-survive" — surviving grants must be revoked before retirement.
136	  ERROR_REASON_GRANTS_SURVIVE = 31;
137	  // "decision-change-unacknowledged" — retiring a static policy needs acknowledgement.
138	  ERROR_REASON_DECISION_CHANGE_UNACKNOWLEDGED = 32;
139	
140	  // ---- Gateway (300-599) ---------------------------------------------------
141	  // Emitted snake_case today; SMA-504 recases them. `type` is untouched and
142	  // keeps its OpenAI semantics.
143	
144	  // "missing-authorization" — no usable Authorization bearer credential.
145	  ERROR_REASON_MISSING_AUTHORIZATION = 300;
146	  // "invalid-api-key" — the credential was rejected by IAM.
147	  ERROR_REASON_INVALID_API_KEY = 301;
148	  // "insufficient-permissions" — identity is authenticated but not permitted.
149	  ERROR_REASON_INSUFFICIENT_PERMISSIONS = 302;
150	  // "missing-scope" — introspection returned no scope PRN.
151	  ERROR_REASON_MISSING_SCOPE = 303;
152	  // "iam-unavailable" — the gateway cannot reach IAM.
153	  ERROR_REASON_IAM_UNAVAILABLE = 304;
154	  // "upstream-unavailable" — the gateway cannot reach the model provider.
155	  ERROR_REASON_UPSTREAM_UNAVAILABLE = 305;
156	  // "upstream-timeout" — the model provider did not respond in time.
157	  ERROR_REASON_UPSTREAM_TIMEOUT = 306;
158	  // "upstream-error" — a streamed response failed mid-flight.
159	  ERROR_REASON_UPSTREAM_ERROR = 307;
160	  // "streaming-disabled" — streamed completions are refused by configuration.
161	  // A request-PARAMETER refusal (400, param "stream"), not a route-level
162	  // capability gate — see ERROR_REASON_CAPABILITY_DISABLED for that.
163	  ERROR_REASON_STREAMING_DISABLED = 308;
164	
165	  // ---- Shared (900-999) ----------------------------------------------------
166	  // Any domain may emit these; `domain` is what distinguishes them.
167	
168	  // "internal" — an unexpected fault; detail stays in logs.
169	  ERROR_REASON_INTERNAL = 900;
170	  // "invalid-request-body" — the request body could not be deserialized; covers IAM's
171	  // invalid_request extractor rejection and the gateway's invalid_request_body, merged.
172	  ERROR_REASON_INVALID_REQUEST_BODY = 901;
173	  // "request-too-large" — request body exceeded the configured byte limit.
174	  ERROR_REASON_REQUEST_TOO_LARGE = 902;
175	  // "missing-auth-context" — the enforcement layer admitted a request without
176	  // attaching an authenticated context. An internal invariant violation,
177	  // surfaced as a distinct diagnostic rather than a bare unauthenticated.
178	  ERROR_REASON_MISSING_AUTH_CONTEXT = 903;
179	  // "capability-disabled" — the RPC belongs to a capability this deployment
180	  // has switched off. The capability name rides in
181	  // ErrorInfo.metadata["capability"], so a new capability needs no new reason.
182	  ERROR_REASON_CAPABILITY_DISABLED = 904;
183	}

