            return None;
        }
        let name = format!("{REASON_PREFIX}{}", reason.to_ascii_uppercase().replace('-', "_"));
        match Self::from_str_name(&name)? {
            Self::Unspecified => None,
            value => Some(value),
        }
    }
}

