```rust
// SPDX-License-Identifier: Apache-2.0

//! A uuid path-segment extractor that answers inside IAM's error envelope (SMA-586 D5.1).
//!
//! axum's own `Path<Uuid>` rejects a malformed segment with a plain-text 400 that is not the
//! `{"error":{code,message}}` contract every other IAM failure uses — so 26 routes answered
//! outside their own error contract, and `invalid-uuid` had no HTTP emitter at all while its
//! gRPC twins did (AC-1). This closes both.
//!
//! Mirrors `authn::EnvelopeJson`, which already does exactly this for `Json<T>` rejections.
//!
//! The field name rides in a request extension rather than a const generic because
//! `&'static str` const-generic parameters are not stable. `field_name` is the route-level
//! layer that sets it; a route that forgets it falls back to `"id"`, which is the literal
//! path-segment name and so is never wrong, only less specific.

use axum::extract::{FromRequestParts, Path};
use axum::http::request::Parts;
use axum::response::{IntoResponse, Response};
use tower_http::add_extension::AddExtensionLayer;
use uuid::Uuid;

use crate::adapters::http::error::ApiError;
use crate::application::error::TenancyError;

/// The field name a route's uuid segment should be called in an error.
#[derive(Debug, Clone, Copy)]
pub(crate) struct UuidFieldName(pub &'static str);

/// Attaches the field name [`UuidPath`] reports on a rejection.
pub(crate) fn field_name(name: &'static str) -> AddExtensionLayer<UuidFieldName> {
    AddExtensionLayer::new(UuidFieldName(name))
}

fn name_of(parts: &Parts) -> &'static str {
    parts.extensions.get::<UuidFieldName>().map(|n| n.0).unwrap_or("id")
}

/// A single uuid path segment.
pub(crate) struct UuidPath(pub Uuid);

impl<S: Send + Sync> FromRequestParts<S> for UuidPath {
    type Rejection = Response;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let field = name_of(parts);
        match Path::<Uuid>::from_request_parts(parts, state).await {
            Ok(Path(id)) => Ok(UuidPath(id)),
            Err(_) => Err(ApiError(TenancyError::InvalidUuid(field)).into_response()),
        }
    }
}

/// Two uuid path segments, for `/{sa}/api-keys/{id}`. Both are reported under the SAME field
/// name: axum's `PathRejection` does not say which segment failed, and inventing one would be
/// a guess presented as fact.
pub(crate) struct UuidPathPair(pub Uuid, pub Uuid);

impl<S: Send + Sync> FromRequestParts<S> for UuidPathPair {
    type Rejection = Response;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let field = name_of(parts);
        match Path::<(Uuid, Uuid)>::from_request_parts(parts, state).await {
            Ok(Path((a, b))) => Ok(UuidPathPair(a, b)),
            Err(_) => Err(ApiError(TenancyError::InvalidUuid(field)).into_response()),
        }
    }
}
```

